        avgEvidenceHealth,
        dataFreshnessScore: 0.92,
        modelCoverageScore: 0.87,
        actionQueueBacklog: actionQueue.filter((a)=>a.status !== 'COMPLETED').length,
        overdueActions: actionQueue.filter((a)=>a.status === 'OVERDUE').length,
